#!/usr/bin/env python3
"""Generates src/basisu/astc_hdr_downsample_tables.rs from basisu_astc_hdr_common.cpp:
the SLSQP 6x6 -> grid weight downsample matrices (g_weight_downsample_6x6_to_WxH)."""
import os
import re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, "ref/ktx/external/basis_universal/encoder/basisu_astc_hdr_common.cpp")
DST = os.path.join(ROOT, "src/basisu/astc_hdr_downsample_tables.rs")

src = open(SRC).read()
out = [
    "//! Generated by scripts/gen_basisu_hdr_downsample_tables.py from basisu_astc_hdr_common.cpp:",
    "//! the 6x6 block -> weight grid downsample matrices (`g_weight_downsample_6x6_to_*`). For each",
    "//! grid sample (row major), the weight of each of the 36 block samples.",
    "",
]
entries = []
for m in re.finditer(r"static const float g_weight_downsample_6x6_to_(\d)x(\d)\[(\d+)\]\[36\] = \{(.*?)\n\};", src, re.S):
    gw, gh, n, body = int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4)
    vals = re.findall(r"-?\d+\.\d+(?:e[-+]?\d+)?f", body)
    assert len(vals) == n * 36, (gw, gh, len(vals))
    name = f"DOWNSAMPLE_6X6_TO_{gw}X{gh}"
    out.append(f"pub const {name}: [f32; {n * 36}] = [")
    for i in range(0, len(vals), 6):
        out.append("    " + ", ".join(v[:-1] for v in vals[i:i + 6]) + ",")
    out.append("];")
    out.append("")
    entries.append((gw, gh, name))

order = re.findall(r"\{ (\d), (\d), \(const float\*\)g_weight_downsample_6x6_to_\dx\d \}", src.split("g_downsample_matrices_6x6[] =")[1].split("};")[0])
assert len(order) == 25 and len(entries) == 25
out.append("/// `g_downsample_matrices_6x6`: (grid width, grid height, matrix).")
out.append("pub const DOWNSAMPLE_MATRICES_6X6: [(u32, u32, &[f32]); 25] = [")
for gw, gh in order:
    out.append(f"    ({gw}, {gh}, &DOWNSAMPLE_6X6_TO_{gw}X{gh}),")
out.append("];")
open(DST, "w").write("\n".join(out) + "\n")
print("wrote", DST)
